/* From Uiverse.io by shadowmurphy - Tags: simple, material design, neumorphism, card */
.__UIV_SCOPE__ .card {
  width: 350px;
  height: 150px;
  background: #262626;
  border-radius: 10px;
  border: 1px solid #3F3F40;
}

.__UIV_SCOPE__ a {
  text-decoration: none;
}

.__UIV_SCOPE__ header, .__UIV_SCOPE__ footer, .__UIV_SCOPE__ main {
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ header {
  justify-content: space-between;
  margin: 20px;
  color: #BDBFB7;
}

.__UIV_SCOPE__ header a {
  font-size: 15px;
  cursor: pointer;
  color: #BDBFB7
}

.__UIV_SCOPE__ main {
  justify-content: flex-start;
  margin: 20px;
}

.__UIV_SCOPE__ main p {
  color: white;
  font-weight: 600;
}

.__UIV_SCOPE__ main a {
  color: #BDBFB7;
  font-weight: 100;
}

.__UIV_SCOPE__ footer {
  margin: 20px;
  font-size: 15px;
  gap: 5px;
}

.__UIV_SCOPE__ footer a {
  color: #2CAD3D;
  font-weight: 600;
}

.__UIV_SCOPE__ footer p {
  color: white;
}
